<?php
declare(strict_types=1);
require_once __DIR__.'/../core/Model.php';
final class Tienda extends Model {
 public function favoritos(int $u): array {$q=$this->pdo->prepare('SELECT p.* FROM favoritos f JOIN productos p ON p.id=f.id_producto WHERE f.id_usuario=? ORDER BY p.nombre');$q->execute([$u]);return $q->fetchAll();}
 public function favorito(int $u,int $p,bool $add): void {if($add){$q=$this->pdo->prepare('INSERT IGNORE INTO favoritos(id_usuario,id_producto) VALUES(?,?)');$q->execute([$u,$p]);}else{$this->pdo->prepare('DELETE FROM favoritos WHERE id_usuario=? AND id_producto=?')->execute([$u,$p]);}}
 public function carrito(int $u): array {$q=$this->pdo->prepare('SELECT d.*,p.nombre,p.imagen FROM detalles_carrito d JOIN carrito c ON c.id_carrito=d.id_carrito JOIN productos p ON p.id=d.id_producto WHERE c.id_usuario=? AND c.estado=\'abierto\'');$q->execute([$u]);return $q->fetchAll();}
 public function agregar(int $u,int $p,int $cantidad): void {$this->pdo->beginTransaction();$q=$this->pdo->prepare('SELECT id_carrito FROM carrito WHERE id_usuario=? AND estado=\'abierto\'');$q->execute([$u]);$c=$q->fetchColumn();if(!$c){$this->pdo->prepare('INSERT INTO carrito(id_usuario,estado) VALUES(?,\'abierto\')')->execute([$u]);$c=$this->pdo->lastInsertId();}$precio=$this->pdo->prepare('SELECT precio FROM productos WHERE id=?');$precio->execute([$p]);$v=$precio->fetchColumn();$q=$this->pdo->prepare('INSERT INTO detalles_carrito(id_carrito,id_producto,cantidad,precio_unitario) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE cantidad=cantidad+VALUES(cantidad)');$q->execute([$c,$p,$cantidad,$v]);$this->pdo->commit();}
 public function quitar(int $u,int $p): void {$this->pdo->prepare('DELETE d FROM detalles_carrito d JOIN carrito c ON c.id_carrito=d.id_carrito WHERE c.id_usuario=? AND d.id_producto=?')->execute([$u,$p]);}
 public function actualizar(int $u,int $p,int $cantidad): void { if($cantidad<=0){$this->quitar($u,$p);return;} $q=$this->pdo->prepare('UPDATE detalles_carrito d JOIN carrito c ON c.id_carrito=d.id_carrito SET d.cantidad=? WHERE c.id_usuario=? AND d.id_producto=?');$q->execute([$cantidad,$u,$p]); }
 public function vaciar(int $u): void {$this->pdo->prepare('DELETE d FROM detalles_carrito d JOIN carrito c ON c.id_carrito=d.id_carrito WHERE c.id_usuario=? AND c.estado=\'abierto\'')->execute([$u]);}
 public function comprar(int $u): int {$items=$this->carrito($u);if(!$items)throw new Exception('El carrito está vacío');$total=array_sum(array_map(fn($i)=>(float)$i['precio_unitario']*$i['cantidad'],$items));$this->pdo->beginTransaction();$q=$this->pdo->prepare('INSERT INTO compras(id_usuario,total,fecha) VALUES(?,?,NOW())');$q->execute([$u,$total]);$id=(int)$this->pdo->lastInsertId();foreach($items as $i){$this->pdo->prepare('INSERT INTO detalles_compra(id_compra,id_producto,cantidad,precio_unitario,subtotal) VALUES(?,?,?,?,?)')->execute([$id,$i['id_producto'],$i['cantidad'],$i['precio_unitario'],$i['precio_unitario']*$i['cantidad']]);}$this->pdo->prepare('DELETE d FROM detalles_carrito d JOIN carrito c ON c.id_carrito=d.id_carrito WHERE c.id_usuario=?')->execute([$u]);$this->pdo->commit();return $id;}
 public function compras(int $u): array {$q=$this->pdo->prepare('SELECT * FROM compras WHERE id_usuario=? ORDER BY fecha DESC');$q->execute([$u]);return $q->fetchAll();}
}
